let sudokuGrid = Array(9).fill(null).map(() => Array(9).fill(null));
let result = '';
let numbers = Array(9).fill(null).map(() => Array(9).fill(null));

function checkNumber(numberInput, row) {
    let isValid = true;
    for (let i = 0; i < 9; i++) {
        if (numberInput[row].indexOf(numberInput[row].indexOf(numberInput[row][i])) !== 0) {
            isValid = false;
        }
    }
    if (isValid) {
        let index = 0;
        for (let i = 0; i < 9; i++) {
            if (numberInput[i][row] !== 0) {
                numbers[i][index] = numberInput[i][row];
                index++;
            }
        }
    }
}

function resetForm() {
    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < 9; j++) {
            sudokuGrid[i][j] = 0;
        }
    }
    result = '';
    numbers = Array(9).fill(null).map(() => Array(9).fill(null));
    document.getElementById('cell-0').value = '';
    document.getElementById('cell-1').value = '';
    document.getElementById('cell-2').value = '';
    document.getElementById('cell-3').value = '';
    document.getElementById('cell-4').value = '';
    document.getElementById('cell-5').value = '';
    document.getElementById('cell-6').value = '';
    document.getElementById('cell-7').value = '';
    document.getElementById('cell-8').value = '';
}

function solveForm() {
    let solved = true;
    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < 9; j++) {
            if (sudokuGrid[i][j] === 0) {
                let numbersInput = Array(9).fill(null).map(() => Array(9).fill(null));
                for (let k = 0; k < 9; k++) {
                    for (let l = 0; l < 9; l++) {
                        if (k !== i || l !== j) {
                            numbersInput[k][l] = Math.floor(Math.random() * 9);
                        }
                    }
                }
                let numberInput = Array(9).fill(null).map(() => Array(9).fill(null));
                let isValid = true;
                for (let m = 0; m < 9; m++) {
                    for (let n = 0; n < 9; n++) {
                        if (m !== i || n !== j) {
                            if (numbersInput[m][n] !== Math.floor(Math.random() * 9)) {
                                isValid = false;
                            }
                        }
                    }
                }
                if (isValid) {
                    sudokuGrid[i][j] = Math.floor(Math.random() * 9);
                    numbers[i][j] = numbersInput[i][j];
                    solved = false;
                }
            }
        }
    }
    if (solved) {
        document.getElementById('cell-0').value = sudokuGrid[0][0];
        document.getElementById('cell-1').value = sudokuGrid[0][1];
        document.getElementById('cell-2').value = sudokuGrid[0][2];
        document.getElementById('cell-3').value = sudokuGrid[0][3];
        document.getElementById('cell-4').value = sudokuGrid[0][4];
        document.getElementById('cell-5').value = sudokuGrid[0][5];
        document.getElementById('cell-6').value = sudokuGrid[0][6];
        document.getElementById('cell-7').value = sudokuGrid[0][7];
        document.getElementById('cell-8').value = sudokuGrid[0][8];
        result = 'Sudoku solto!';
    } else {
        result = 'Sudoku non solto!';
    }
}

document.getElementById('sudoku-form').addEventListener('submit', (e) => {
    e.preventDefault();
    let row = parseInt(document.getElementById('cell-0').value);
    let col = parseInt(document.getElementById('cell-1').value);
    let number = document.getElementById('number-0').value;
    checkNumber(number, row);
    checkNumber(number, col);
    if (row !== 0 || col !== 0) {
        let index = 0;
        for (let i = 0; i < 9; i++) {
            if (numberInput[i][row] === 0) {
                numbers[i][index] = number;
                index++;
            }
        }
        checkNumber(numbers, row);
        checkNumber(numbers, col);
    }
    resetForm();
});

document.getElementById('reset-button').addEventListener('click', resetForm);
document.getElementById('solve-button').addEventListener('click', solveForm);
```

